"""로멜루 루카쿠 설명(NOTE) 문구. build_lukaku.py 가 globals()를 넘겨 부른다."""

KO = {"andrl": "안데를레흐트", "cherl": "첼시", "wbarl": "웨스트브로미치", "everl": "에버턴", "munrl": "맨유",
      "intrl": "인테르", "romrl": "로마", "naprl": "나폴리", "fenrl": "페네르바흐체"}

def make_note(g):
    ST, NG, NGo, NA, NPK, MIN_TOT = g["ST"], g["NG"], g["NGo"], g["NA"], g["NPK"], g["MIN_TOT"]
    NTIE, NTIEG, SRC_A = g["NTIE"], g["NTIEG"], g["SRC_A"]
    M = g["M"]
    first, last = M[0], M[-1]
    def dd(s): y, m, d = s.split("-"); return f"{int(y)}.{int(m)}.{int(d)}"
    clubs = ", ".join(f"{KO[k]} {v[0]}·{v[1]}·{v[2]}" for k, v in ST.items())
    L = []
    L.append(f"로멜루 루카쿠(안데를레흐트·첼시·웨스트브로미치·에버턴·맨체스터 유나이티드·인테르·로마·나폴리·페네르바흐체)의 클럽 공식 경기 {NG}경기"
             f"({dd(first[0])} 스탕다르전 ~ {dd(last[0])} 초룸전)에서 나온 {NGo}골 {NA}도움, 친선경기 제외")
    L.append(f"클럽별 경기·골·도움: {clubs} (첼시는 2011-12·2013-14·2021-22, 인테르는 2019~2021·2022-23 임대를 합친 값). 출전 분 합계 {MIN_TOT:,}분")
    L.append("출전 경기·출전 분·선발 여부는 Transfermarkt 선수 경기 성적 기준, 골 시간·골 뒤 스코어·PK·도움은 Transfermarkt 경기 리포트 기준")
    L.append("경기 수·골 수는 영어·프랑스어 위키백과 시즌별 기록(697경기 317골)과 FotMob 클럽별 통산 경기·골과 모두 같음(영어 위키백과 통산 줄은 316골이지만 시즌 줄 합계는 317골)")
    L.append("안데를레흐트 U19(비아레조 대회 2경기 1골)·첼시 U21(리저브 리그 9경기 7골 1도움)·대표팀 경기는 넣지 않음")
    L.append("벨기에 1부 챔피언십 플레이오프(2009-10 8경기·2010-11 9경기)는 위키백과처럼 리그 경기로 계산하고, 2009.5.24 데뷔전(스탕다르와 승점이 같아 치른 2008-09 우승 결정전 2차전, 25분)도 리그 경기와 같은 비중으로 넣음")
    L.append("2009.9.24 무스크롱 원정(74분 골)은 무스크롱이 그해 12월 파산해 시즌 결과가 지워졌지만, 실제로 끝까지 치른 경기이고 리그 공식 득점 순위(루카쿠 15골 득점왕)에 이 골이 들어 있어 출전과 골을 모두 넣음")
    L.append(f"FotMob 경기 기록과 맞춰 보니 2010년 7월 이후 골은 골 뒤 스코어·PK가 모두 같음(시간 1분 차이와 FotMob이 45·90분으로만 적은 추가시간은 Transfermarkt 기준). PK 골 {NPK}개. FotMob 자료가 없는 2009-10시즌까지의 골은 Transfermarkt만 기준")
    L.append("2020.8.21 유로파리그 결승 세비야전: 5분 PK 골은 넣고, Transfermarkt 리포트의 본인 PK 골 본인 도움 표기는 도움에 넣지 않음. 74분 루카쿠 자책골은 골이 아님")
    L.append(f"도움 {NA}개 = 2014년 7월까지 Transfermarkt 리포트 도움 {SRC_A['2014.8 전 Transfermarkt']}개(유형 빈칸 포함, 데 브라위너·나니와 같은 기준) + 2014년 8월 이후 Transfermarkt와 FotMob 경기 기록이 함께 센 {SRC_A['TM∩FotMob 경기 이벤트']}개")
    L.append("Transfermarkt 도움 102개에서 뺀 5개: 슈팅 리바운드 1개(2009.10.1 아약스전 85분 레가르), PK 유도 2개(2021.10.20 말뫼전 21분·2021.12.26 애스턴 빌라전 90+3분 조르지뉴 PK), 흘러나온 공 1개(2013.12.8 아스널전 84분 데울로페우 골: AP 경기 기사는 루카쿠의 오버헤드킥이 공에 맞지 않은 뒤 데울로페우가 넣은 골로 적고, FotMob은 오비에도 도움으로 적음)")
    L.append("확인 못 해 뺀 Transfermarkt 단독 도움 1개: 2016.8.23 리그컵 요빌 타운전 83분 코네 골(FotMob 도움자 없음, ESPN 문자 중계만 루카쿠 도움, PA 경기 기사는 도움 서술 없음)")
    L.append("FotMob에만 있는 도움은 없음(FotMob 선수 경기 목록이 2020.11.22 토리노전·2021.3.4 파르마전을 도움 2개로 적었지만 FotMob 경기 기록·Transfermarkt는 1개)")
    L.append("위키백과 시즌 도움 합계는 네덜란드어판 98개·프랑스어판 111개로 Transfermarkt(102개)와 시즌마다 조금씩 다름(경기별 근거가 없어 쓰지 않음)")
    L.append("2025-26시즌 나폴리는 2025년 8월 부상으로 2026년 1월까지 출전이 없어 7경기만 뜀")
    L.append("날짜는 경기 현지 날짜(2022.2 클럽 월드컵 아부다비 경기도 현지 저녁이라 Transfermarkt 날짜와 같음)")
    L.append("상대 Elo는 같은 경기를 다룬 다른 선수 자료의 값, 상대 팀×시즌 통합표 값을 먼저 쓰고, 없으면 그 시즌 최종 순위(Transfermarkt 순위표, 진행 중인 2026-27 쉬페르리그는 11월 18일 현재 순위)와 다른 선수 자료의 순위별 값으로 구함")
    L.append("벨기에 1부 순위는 다른 선수 자료와 같이 챔피언십 플레이오프 1~6위 뒤 정규 시즌 순서(메헬렌 2011-12 9위는 다른 선수 자료 8위·10위 값 사이)")
    L.append("잉글랜드 2·3부 상대(미들즈브러 2015-16 2위·더비 2017-18 6위·레딩 2018-19 20위·반즐리 2015-16 리그 원 6위)는 다른 선수 자료의 같은 순위 값(시즌과 무관하게 같음)을 씀. 팔레르모 2024-25 세리에B 8위·리제스포르 2026-27 11위는 다른 선수 자료 앞뒤 순위 값 사이, 괴즈테페 2026-27 10위는 같은 순위 값")
    L.append("직접 추정('추정'): 무스크롱 2009-10(기록 삭제, 같은 시즌 꼴찌 값 1277), 더 뉴 세인츠 2010-11(웨일스 2위, 1200), AEK 아테네 2010-11(그리스 3위, 1550), 영 보이스 2014-15(스위스 2위, 1609), 셰리프 2023-24(몰도바 1위, 1500), 세르베트 2023-24(스위스 3위, 1550), 팔메이라스 2021(브라질 3위, 리그 모형 1671) — 모두 다른 선수 자료의 같은 팀·비슷한 순위 값을 따름. 알힐랄 2021-22(사우디 1위)는 사우디 1위 모형값 1813")
    L.append("벨기에컵·FA컵·리그컵·코파 이탈리아는 국내컵(FA컵 6라운드·리그컵 5라운드는 8강), UEFA 슈퍼컵은 국내컵 결승과 같은 비중, 2020년 8월 유로파리그 단판 16강·8강은 토너먼트, 2024년 이후 챔스 리그 페이즈는 조별과 같은 비중으로 계산함")
    L.append(f"두 경기 합산(챔스 예선·챔스·유로파 토너먼트, 리그컵·코파 이탈리아 준결승) 기록 {NTIE}개({NTIEG}경기)는 합산 S로 계산함. 원정 다득점은 UEFA 대회 2020-21시즌까지, 리그컵 준결승 2017-18시즌까지, 코파 이탈리아 2021-22시즌까지 적용(2019-20 코파 이탈리아 준결승 2차전은 연장 없이 승부차기)")
    L.append("시즌은 8월 1일 기준이되 안데를레흐트는 7월 10일 기준(2011.7.29 리그 개막전 = 2011-12), 2020년 8월 경기는 2019-20시즌")
    L.append(f"2026.11.18 기준(현역, 페네르바흐체): 마지막 경기 {dd(last[0])} 초룸전(쉬페르리그, 57분 1도움)까지 넣음")
    return "\n".join(L)
